export interface Detail {
  key: string;
  /** NUll - removes key */
  value: any | undefined;
}

export interface DeviceInfo {
  id: string;
  name: string;
  addDate: number;
  archived: boolean;
  isConnected: boolean;
}

export interface ChatState {
  /** unread messages */
  messages:
    | ChatState_UnreadState
    | undefined;
  /** unread mentions */
  mentions:
    | ChatState_UnreadState
    | undefined;
  /** reflects the state of the chat db at the moment of sending response/event that includes this state */
  lastStateId: string;
  /** Order is serial number of this state. Client should apply chat state only if its order is greater than previously saved order */
  order: number;
  /** order id of the newest message with any unread reactions */
  unreadReactionOrderId: string;
}

export interface ChatState_UnreadState {
  /** oldest(in the lex sorting) unread message order id. Client should ALWAYS scroll through unread messages from the oldest to the newest */
  oldestOrderId: string;
  /** total number of unread messages */
  counter: number;
}

export interface ChatMessage {
  /** Unique message identifier */
  id: string;
  /** Lexicographical id for message in order of tree traversal */
  orderId: string;
  /** Identifier for the message creator */
  creator: string;
  createdAt: number;
  modifiedAt: number;
  /** stateId is ever-increasing id (BSON ObjectId) for this message. Unlike orderId, this ID is ordered by the time messages are added. For example, it's useful to prevent accidental reading of messages from the past when a ChatReadMessages request is sent: a message from the past may appear, but the client is still unaware of it */
  stateId: string;
  /** Identifier for the message being replied to */
  replyToMessageId: string;
  /** Message content */
  message:
    | ChatMessage_MessageContent
    | undefined;
  /** Attachments slice */
  attachments: ChatMessage_Attachment[];
  /** Reactions to the message */
  reactions:
    | ChatMessage_Reactions
    | undefined;
  /** Message read status */
  read: boolean;
  mentionRead: boolean;
  hasMention: boolean;
  synced: boolean;
  pinned: boolean;
  unreadReaction: boolean;
  /** Ordered list of content blocks */
  blocks: ChatMessage_MessageBlock[];
}

export interface ChatMessage_MessageContent {
  /** The text content of the message part */
  text: string;
  /** The style/type of the message part */
  style: Block_Content_Text_Style;
  /** List of marks applied to the text */
  marks: Block_Content_Text_Mark[];
}

export interface ChatMessage_Attachment {
  /** Identifier for the attachment object */
  target: string;
  /** Type of attachment */
  type: ChatMessage_Attachment_AttachmentType;
}

export enum ChatMessage_Attachment_AttachmentType {
  /** FILE - File attachment */
  FILE = 0,
  /** IMAGE - Image attachment */
  IMAGE = 1,
  /** LINK - Link attachment */
  LINK = 2,
  UNRECOGNIZED = -1,
}

export interface ChatMessage_Reactions {
  /** Map of emoji to list of user IDs */
  reactions: { [key: string]: ChatMessage_Reactions_IdentityList };
}

export interface ChatMessage_Reactions_ReactionsEntry {
  key: string;
  value: ChatMessage_Reactions_IdentityList | undefined;
}

export interface ChatMessage_Reactions_IdentityList {
  /** List of user IDs */
  ids: string[];
}

export interface ChatMessage_MessageBlock {
  text?: ChatMessage_MessageBlockText | undefined;
  link?: ChatMessage_MessageBlockLink | undefined;
  embed?: ChatMessage_MessageBlockEmbed | undefined;
  editorQuote?: ChatMessage_MessageBlockEditorQuote | undefined;
  messageQuote?: ChatMessage_MessageBlockMessageQuote | undefined;
}

export interface ChatMessage_MessageBlockText {
  text: string;
  style: Block_Content_Text_Style;
  marks: Block_Content_Text_Mark[];
  checked: boolean;
  lang: string;
}

export interface ChatMessage_MessageBlockLink {
  targetObjectId: string;
  type: ChatMessage_MessageBlockLink_LinkType;
}

export enum ChatMessage_MessageBlockLink_LinkType {
  Object = 0,
  File = 1,
  Image = 2,
  Bookmark = 3,
  UNRECOGNIZED = -1,
}

export interface ChatMessage_MessageBlockEmbed {
  text: string;
  processor: Block_Content_Latex_Processor;
}

export interface ChatMessage_MessageBlockEditorQuote {
  /** id of the quoted block in the source object */
  blockId: string;
  /** quoted block content (text, style, marks, ...) */
  content: ChatMessage_MessageBlockText | undefined;
}

export interface ChatMessage_MessageBlockMessageQuote {
  /** id of the quoted chat message */
  messageId: string;
  /** id of the participant who authored the quoted message */
  participantId: string;
  /** quoted message content (text, style, marks, ...) */
  content: ChatMessage_MessageBlockText | undefined;
}

export interface Placeholder {
  relationKey: string;
  values: Placeholder_Value[];
}

export enum Placeholder_Type {
  PlaceholderValue = 0,
  PlaceholderToday = 1,
  PlaceholderCurrentUser = 2,
  UNRECOGNIZED = -1,
}

export interface Placeholder_Value {
  type: Placeholder_Type;
  value: any | undefined;
}

function createBaseSmartBlockSnapshotBase(): SmartBlockSnapshotBase {
  return {
    blocks: [],
    details: undefined,
    fileKeys: undefined,
    extraRelations: [],
    objectTypes: [],
    collections: undefined,
    removedCollectionKeys: [],
    relationLinks: [],
    key: "",
    originalCreatedTimestamp: 0,
    fileInfo: undefined,
  };
}

export const SmartBlockSnapshotBase: MessageFns<SmartBlockSnapshotBase> = {
  encode(message: SmartBlockSnapshotBase, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    for (const v of message.blocks) {
      Block.encode(v!, writer.uint32(10).fork()).join();
    }
    if (message.details !== undefined) {
      Struct.encode(Struct.wrap(message.details), writer.uint32(18).fork()).join();
    }
    if (message.fileKeys !== undefined) {
      Struct.encode(Struct.wrap(message.fileKeys), writer.uint32(26).fork()).join();
    }
    for (const v of message.extraRelations) {
      Relation.encode(v!, writer.uint32(34).fork()).join();
    }
    for (const v of message.objectTypes) {
      writer.uint32(42).string(v!);
    }
    if (message.collections !== undefined) {
      Struct.encode(Struct.wrap(message.collections), writer.uint32(50).fork()).join();
    }
    for (const v of message.removedCollectionKeys) {
      writer.uint32(66).string(v!);
    }
    for (const v of message.relationLinks) {
      RelationLink.encode(v!, writer.uint32(58).fork()).join();
    }
    if (message.key !== "") {
      writer.uint32(74).string(message.key);
    }
    if (message.originalCreatedTimestamp !== 0) {
      writer.uint32(80).int64(message.originalCreatedTimestamp);
    }
    if (message.fileInfo !== undefined) {
      FileInfo.encode(message.fileInfo, writer.uint32(90).fork()).join();
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): SmartBlockSnapshotBase {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseSmartBlockSnapshotBase();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.blocks.push(Block.decode(reader, reader.uint32()));
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.details = Struct.unwrap(Struct.decode(reader, reader.uint32()));
          continue;
        }
        case 3: {
          if (tag !== 26) {
            break;
          }

          message.fileKeys = Struct.unwrap(Struct.decode(reader, reader.uint32()));
          continue;
        }
        case 4: {
          if (tag !== 34) {
            break;
          }

          message.extraRelations.push(Relation.decode(reader, reader.uint32()));
          continue;
        }
        case 5: {
          if (tag !== 42) {
            break;
          }

          message.objectTypes.push(reader.string());
          continue;
        }
        case 6: {
          if (tag !== 50) {
            break;
          }

          message.collections = Struct.unwrap(Struct.decode(reader, reader.uint32()));
          continue;
        }
        case 8: {
          if (tag !== 66) {
            break;
          }

          message.removedCollectionKeys.push(reader.string());
          continue;
        }
        case 7: {
          if (tag !== 58) {
            break;
          }

          message.relationLinks.push(RelationLink.decode(reader, reader.uint32()));
          continue;
        }
        case 9: {
          if (tag !== 74) {
            break;
          }

          message.key = reader.string();
          continue;
        }
        case 10: {
          if (tag !== 80) {
            break;
          }

          message.originalCreatedTimestamp = longToNumber(reader.int64());
          continue;
        }
        case 11: {
          if (tag !== 90) {
            break;
          }

          message.fileInfo = FileInfo.decode(reader, reader.uint32());
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  create<I extends Exact<DeepPartial<SmartBlockSnapshotBase>, I>>(base?: I): SmartBlockSnapshotBase {
    return SmartBlockSnapshotBase.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<SmartBlockSnapshotBase>, I>>(object: I): SmartBlockSnapshotBase {
    const message = createBaseSmartBlockSnapshotBase();
    message.blocks = object.blocks?.map((e) => Block.fromPartial(e)) || [];
    message.details = object.details ?? undefined;
    message.fileKeys = object.fileKeys ?? undefined;
    message.extraRelations = object.extraRelations?.map((e) => Relation.fromPartial(e)) || [];
    message.objectTypes = object.objectTypes?.map((e) => e) || [];
    message.collections = object.collections ?? undefined;
    message.removedCollectionKeys = object.removedCollectionKeys?.map((e) => e) || [];
    message.relationLinks = object.relationLinks?.map((e) => RelationLink.fromPartial(e)) || [];
    message.key = object.key ?? "";
    message.originalCreatedTimestamp = object.originalCreatedTimestamp ?? 0;
    message.fileInfo = (object.fileInfo !== undefined && object.fileInfo !== null)
      ? FileInfo.fromPartial(object.fileInfo)
      : undefined;
    return message;
  },
};

